import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"Page 16","description":"","frontmatter":{},"headers":[],"relativePath":"page-16.md","filePath":"page-16.md"}'),l={name:"page-16.md"};function i(n,e,s,d,c,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="page-16" tabindex="-1">Page 16 <a class="header-anchor" href="#page-16" aria-label="Permalink to &quot;Page 16&quot;">​</a></h1><h3 id="stl-容器-map" tabindex="-1">STL 容器 - map <a class="header-anchor" href="#stl-容器-map" aria-label="Permalink to &quot;STL 容器 - map&quot;">​</a></h3><ul><li><p><strong>map</strong></p><ul><li><strong>定义</strong>：<code>map&lt;int, int&gt; a;</code> 不允许重复键（自动去重）</li><li><strong>语句</strong>：<code>a[键] = 值;</code> 如果键存在则修改值，如果不存在则插入新的键值对</li><li>键可以是基本类型或 string 等，不一定是整数。</li><li>值可以是基本类型或其他类型。</li><li><strong>函数</strong>：<code>a.size();</code> <code>a.empty();</code> <code>a.clear();</code> <code>a.begin();</code> <code>a.end();</code> // 同 vector <code>a.insert();</code> // 插入键值对，不重复 <code>a.erase();</code> // 删除键值对 <code>a.count();</code> // 返回键是否存在（0或1）</li></ul></li><li><p><strong>multimap</strong></p><ul><li><strong>定义</strong>：<code>multimap&lt;int, int&gt; a;</code> 允许重复键</li><li><strong>语句</strong>：同 map</li><li><strong>函数</strong>：同 map，<code>a.find()</code> 只返回第一个匹配项</li></ul></li><li><p><strong>unordered_map</strong></p><ul><li><strong>定义</strong>：<code>unordered_map&lt;int, int&gt; a;</code> 不允许重复键</li><li><strong>语句</strong>：同 map</li><li><strong>函数</strong>：同 map</li></ul></li></ul>',3)])])}const _=t(l,[["render",i]]);export{m as __pageData,_ as default};
